# Run the five open models on the audited benchmark configurations.
#
# Set DATASET_DIR to a directory containing the frozen TSV names documented in
# results/README.md to reproduce the audited dataset snapshots. Live
# HuggingFace data requires the explicit ALLOW_LIVE_DATASETS=1 opt-in.
# Hosted-model result files are portable inputs to postprocessing and are not
# generated by this public script.

set -euo pipefail

cd "$(dirname "$0")/.."

RESULTS_DIR="${RESULTS_DIR:-results/rerun}"
DATASET_DIR="${DATASET_DIR:-}"
PYTHON_BIN="${PYTHON_BIN:-python}"
ALLOW_RESUME="${ALLOW_RESUME:-0}"
ALLOW_LIVE_DATASETS="${ALLOW_LIVE_DATASETS:-0}"

if [[ -z "$DATASET_DIR" && "$ALLOW_LIVE_DATASETS" != "1" ]]; then
    echo "DATASET_DIR is required for a gold run. Set ALLOW_LIVE_DATASETS=1 for a non-gold live-dataset run." >&2
    exit 2
fi
if [[ -d "$RESULTS_DIR" ]]; then
    if [[ -n "$(ls -A "$RESULTS_DIR")" && "$ALLOW_RESUME" != "1" ]]; then
        echo "$RESULTS_DIR is not empty. Choose a fresh directory or set ALLOW_RESUME=1 explicitly." >&2
        exit 2
    fi
fi
mkdir -p "$RESULTS_DIR"

validation_manifest_args=()
if [[ -z "$DATASET_DIR" ]]; then
    validation_manifest_args=(--allow-non-gold-manifests)
fi

dataset_file_for() {
    local benchmark="$1"
    if [[ -z "$DATASET_DIR" ]]; then
        return
    fi
    case "$benchmark" in
        boolq) echo "$DATASET_DIR/google_boolq_validation.tsv" ;;
        anli_r1) echo "$DATASET_DIR/facebook_anli_test_r1.tsv" ;;
        anli_r2) echo "$DATASET_DIR/facebook_anli_test_r2.tsv" ;;
        anli_r3) echo "$DATASET_DIR/facebook_anli_test_r3.tsv" ;;
        winogrande) echo "$DATASET_DIR/allenai_winogrande_validation.tsv" ;;
        race) echo "$DATASET_DIR/race_test.tsv" ;;
        lambada) echo "$DATASET_DIR/lambada_test.tsv" ;;
    esac
}

run_model() {
    local gpu="$1"
    local model="$2"
    local model_set="$3"
    local benchmark pregrouper budget data_file batch_size
    batch_size=8
    if [[ "$model" == "qwen2.5-14b-instruct" ]]; then
        batch_size=2
    fi
    while read -r benchmark pregrouper budget; do
        data_file="$(dataset_file_for "$benchmark")"
        if [[ -n "$data_file" && ! -f "$data_file" ]]; then
            echo "Missing frozen dataset: $data_file" >&2
            exit 2
        fi
        local args=(
            -m benchmark_scripts.run_benchmark
            --benchmark "$benchmark"
            --pregrouper "$pregrouper"
            --phases "attention,ablation"
            --model-set "$model_set"
            --results-dir "$RESULTS_DIR"
        )
        if [[ "$budget" != "-" ]]; then
            args+=(--max-forward-passes "$budget" --batch-size "$batch_size")
        fi
        if [[ "$ALLOW_RESUME" == "1" ]]; then
            args+=(--overwrite-existing)
        fi
        if [[ -n "$data_file" ]]; then
            args+=(--dataset-file "$data_file")
        fi
        echo "[$(date)] GPU $gpu: $benchmark/$pregrouper $model"
        CUDA_VISIBLE_DEVICES="$gpu" BENCHMARK_MODELS="$model" \
            "$PYTHON_BIN" "${args[@]}"
    done <<'EOF'
boolq sentence -
anli_r1 sentence -
anli_r2 sentence -
anli_r3 sentence -
winogrande sentence -
race sentence -
boolq word 10000
lambada word 10000
EOF
}

run_layer_model() {
    local gpu="$1"
    local model="$2"
    local model_set="$3"
    local benchmark data_file
    for benchmark in anli_r1 anli_r2 anli_r3 boolq; do
        data_file="$(dataset_file_for "$benchmark")"
        local args=(
            -m benchmark_scripts.run_layerwise
            --benchmark "$benchmark"
            --pregrouper sentence
            --batch-size 32
            --seed 42
            --model-set "$model_set"
            --models "$model"
            --results-dir "$RESULTS_DIR"
        )
        if [[ "$ALLOW_RESUME" == "1" ]]; then
            args+=(--overwrite-existing)
        fi
        if [[ -n "$data_file" ]]; then
            args+=(--dataset-file "$data_file")
        fi
        echo "[$(date)] GPU $gpu: layerwise $benchmark/sentence $model"
        CUDA_VISIBLE_DEVICES="$gpu" "$PYTHON_BIN" "${args[@]}"
    done
}

# Establish the model-independent segment grids before parallel workers start.
while read -r benchmark pregrouper budget; do
    data_file="$(dataset_file_for "$benchmark")"
    if [[ -n "$data_file" && ! -f "$data_file" ]]; then
        echo "Missing frozen dataset: $data_file" >&2
        exit 2
    fi
    args=(
        -m benchmark_scripts.run_benchmark
        --benchmark "$benchmark"
        --pregrouper "$pregrouper"
        --results-dir "$RESULTS_DIR"
    )
    if [[ "$budget" != "-" ]]; then
        args+=(--max-forward-passes "$budget" --batch-size 8)
    fi
    if [[ -n "$data_file" ]]; then
        args+=(--dataset-file "$data_file")
    fi
    BENCHMARK_MODELS=none "$PYTHON_BIN" "${args[@]}"
done <<'EOF'
boolq sentence -
anli_r1 sentence -
anli_r2 sentence -
anli_r3 sentence -
winogrande sentence -
race sentence -
boolq word 10000
lambada word 10000
EOF

# Fail before loading any model if a frozen dataset or generated coordinate
# grid differs from the audited gold inputs.
preflight_args=(
    --results-dir "$RESULTS_DIR"
    --manifests-only
    --skip-manifest
    "${validation_manifest_args[@]}"
)
if [[ -n "$DATASET_DIR" ]]; then
    preflight_args+=(--dataset-dir "$DATASET_DIR")
fi
"$PYTHON_BIN" -m benchmark_scripts.validate_results "${preflight_args[@]}"

# Balance the larger models across two GPUs. Each runner loads one model at a
# time, so no process relies on automatic multi-GPU sharding.
(
    run_model 0 qwen2.5-14b-instruct Qwen2.5-Instruct
    run_model 0 qwen2.5-3b-instruct Qwen2.5-Instruct
) &
worker_0=$!
(
    run_model 1 llama-3.1-8b-instruct Llama3.1-Instruct
    run_model 1 qwen2.5-7b-instruct Qwen2.5-Instruct
    run_model 1 qwen2.5-0.5b-instruct Qwen2.5-Instruct
) &
worker_1=$!

worker_failed=0
for worker in "$worker_0" "$worker_1"; do
    if ! wait "$worker"; then
        worker_failed=1
    fi
done
if [[ "$worker_failed" != 0 ]]; then
    echo "At least one GPU worker failed" >&2
    exit 1
fi

while read -r benchmark pregrouper; do
    "$PYTHON_BIN" -m benchmark_scripts.normalize_segment_outputs \
        "$RESULTS_DIR/$benchmark/$pregrouper"
    "$PYTHON_BIN" -m benchmark_scripts.consolidate_results \
        --benchmark "$benchmark" \
        --pregrouper "$pregrouper" \
        --results-dir "$RESULTS_DIR"
    if [[ "$benchmark" != "lambada" ]]; then
        "$PYTHON_BIN" -m benchmark_scripts.compute_logodds \
            --benchmark "$benchmark" \
            --pregrouper "$pregrouper" \
            --results-dir "$RESULTS_DIR"
    fi
done <<'EOF'
boolq sentence
anli_r1 sentence
anli_r2 sentence
anli_r3 sentence
winogrande sentence
race sentence
boolq word
lambada word
EOF

while read -r model model_directory; do
    "$PYTHON_BIN" -m benchmark_scripts.seal_open_provenance \
        --results-dir "$RESULTS_DIR" \
        --model "$model" \
        --model-path "/tmp/models/$model_directory"
done <<'EOF'
qwen2.5-0.5b-instruct Qwen2.5-0.5B-Instruct
qwen2.5-3b-instruct Qwen2.5-3B-Instruct
qwen2.5-7b-instruct Qwen2.5-7B-Instruct
qwen2.5-14b-instruct Qwen2.5-14B-Instruct
llama-3.1-8b-instruct Meta-Llama-3.1-8B-Instruct
EOF

# Generate the complete scalar-only layer matrix required by the canonical
# ANLI alignment and matched-depth analyses.
(
    run_layer_model 0 llama-3.1-8b-instruct Llama3.1-Instruct
    run_layer_model 0 qwen2.5-7b-instruct Qwen2.5-Instruct
    run_layer_model 0 qwen2.5-0.5b-instruct Qwen2.5-Instruct
) &
layer_worker_0=$!
(
    run_layer_model 1 qwen2.5-14b-instruct Qwen2.5-Instruct
    run_layer_model 1 qwen2.5-3b-instruct Qwen2.5-Instruct
) &
layer_worker_1=$!

layer_worker_failed=0
for worker in "$layer_worker_0" "$layer_worker_1"; do
    if ! wait "$worker"; then
        layer_worker_failed=1
    fi
done
if [[ "$layer_worker_failed" != 0 ]]; then
    echo "At least one layerwise GPU worker failed" >&2
    exit 1
fi

cohort="paper"
for config in \
    boolq/sentence boolq/word \
    anli_r1/sentence anli_r2/sentence anli_r3/sentence \
    winogrande/sentence race/sentence lambada/word; do
    for model in \
        llama3.1-8b-instruct llama3.1-70b-instruct llama3.3-70b-instruct \
        llama4-maverick-17b-128e-instruct gpt-4o gpt-4-1 \
        gemini-2-5-flash-lite-vertex; do
        if [[ ! -f "$RESULTS_DIR/$config/${model}_segment.tsv.gz" ]]; then
            cohort="open"
        fi
    done
done

# Validate raw inputs before producing any derived table.
"$PYTHON_BIN" -m benchmark_scripts.validate_results \
    --results-dir "$RESULTS_DIR" --cohort "$cohort" --skip-manifest \
    "${validation_manifest_args[@]}"

f_table_args=(--cohort paper)
suffix=""
if [[ "$cohort" == "open" ]]; then
    f_table_args=(--cohort open)
    suffix="_open"
    echo "Hosted outputs are absent; writing explicitly open-only tables."
fi

"$PYTHON_BIN" -m benchmark_scripts.f_table \
    --results-dir "$RESULTS_DIR" \
    --output "$RESULTS_DIR/f_table${suffix}.tsv" \
    "${f_table_args[@]}"
"$PYTHON_BIN" -m benchmark_scripts.f_table \
    --results-dir "$RESULTS_DIR" \
    --output "$RESULTS_DIR/f_table_finite_extreme_sensitivity${suffix}.tsv" \
    --api-infinity-policy finite_extreme \
    "${f_table_args[@]}"
"$PYTHON_BIN" -m benchmark_scripts.race_rv \
    --results-dir "$RESULTS_DIR" \
    --output "$RESULTS_DIR/race_rv${suffix}.tsv" \
    --cohort "$cohort"
"$PYTHON_BIN" -m benchmark_scripts.anli_rv \
    --results-dir "$RESULTS_DIR" \
    --output "$RESULTS_DIR/anli_rv${suffix}.tsv" \
    --cohort "$cohort"
"$PYTHON_BIN" -m benchmark_scripts.layerwise_fidelity \
    --results-dir "$RESULTS_DIR" \
    --output "$RESULTS_DIR/layerwise_fidelity.tsv"

"$PYTHON_BIN" -m benchmark_scripts.validate_results \
    --results-dir "$RESULTS_DIR" --cohort "$cohort" --require-derived \
    "${validation_manifest_args[@]}"
